const addSignalProperty = (object: unknown) => {
  Object.defineProperty(object, 'signal', {
    enumerable: true,
    get: () => {
      if (context.signal.aborted) {
        cancelled = true
      } else {
        context.signal.addEventListener('abort', () => {
          cancelled = true
        })
      }
      return context.signal
    },
  })
}

get: () => {
  if (context.signal.aborted) {
    cancelled = true
  } else {
    context.signal.addEventListener('abort', () => {
